THEME = ("T01", "Fondamentaux du contrôle d'accès")
SOURCE = "NIST SP 800-12 rév. 1 (2017) ; ISO/IEC 27002:2022 §5.15 ; Saltzer et Schroeder, « The Protection of Information in Computer Systems », 1975 ⚠ à vérifier"
Q = [
(1,"Quelle étape consiste à vérifier l'identité annoncée par un utilisateur ?","L'authentification","L'autorisation","La journalisation","La classification",
 "L'authentification prouve qui est l'utilisateur ; l'autorisation décide ensuite ce qu'il a le droit de faire."),
(1,"Quelle étape décide si un utilisateur déjà identifié peut lire un fichier ?","L'autorisation","L'authentification","La sauvegarde","Le chiffrement du disque",
 "L'autorisation compare l'identité et les droits à la politique d'accès ; elle suit l'authentification."),
(1,"Que signifie le principe du moindre privilège ?","Chacun reçoit seulement les droits nécessaires à sa mission","Chacun reçoit les droits les plus faibles du système","Les administrateurs ne reçoivent aucun droit","Les droits sont retirés après chaque connexion",
 "Limiter les droits au strict nécessaire réduit ce qu'un compte compromis permet à un attaquant."),
(1,"Dans « AAA », que désigne le dernier A (Accounting) ?","La traçabilité des actions réalisées","L'accès anonyme","L'attribution automatique des droits","L'archivage des mots de passe",
 "Accounting désigne l'enregistrement de ce qui a été fait (qui, quand, quoi) pour pouvoir auditer."),
(1,"Qu'est-ce qu'un sujet dans un modèle de contrôle d'accès ?","L'entité active qui demande un accès, comme un utilisateur ou un processus","La ressource protégée","La règle de la politique","Le journal d'événements",
 "Le sujet agit ; l'objet est la ressource visée ; la politique relie les deux."),
(1,"Qu'est-ce qu'un objet dans un modèle de contrôle d'accès ?","La ressource protégée, comme un fichier ou une table","L'utilisateur connecté","L'administrateur du serveur","Le protocole réseau utilisé",
 "Un objet est ce qu'on protège : fichier, dossier, base de données, imprimante, API."),
(1,"Quel est le rôle d'une politique de contrôle d'accès ?","Définir qui peut faire quoi sur quelles ressources","Chiffrer toutes les communications","Sauvegarder les données chaque nuit","Mesurer la charge des serveurs",
 "La politique exprime les règles d'autorisation que le mécanisme du système applique ensuite."),
(1,"Quelle est la différence entre une politique et un mécanisme de contrôle d'accès ?","La politique dit ce qui est permis, le mécanisme l'applique","La politique est technique, le mécanisme est juridique","Il n'y a aucune différence","Le mécanisme dit ce qui est permis, la politique l'applique",
 "Séparer politique et mécanisme permet de changer les règles sans réécrire le système."),
(1,"Que signifie « besoin d'en connaître » ?","L'accès à une information est limité aux personnes qui en ont besoin pour leur travail","Toute personne habilitée peut tout lire","Seul le propriétaire connaît le contenu","L'information doit être connue de tous les services",
 "Même habilitée, une personne n'accède pas à ce qui ne sert pas sa mission."),
(1,"Quel principe impose de répartir une opération sensible entre plusieurs personnes ?","La séparation des tâches","La délégation illimitée","La rotation des mots de passe","Le chiffrement symétrique",
 "Si deux personnes doivent intervenir, une fraude suppose leur collusion, donc devient plus difficile."),
(1,"Quel risque la séparation des tâches réduit-elle en priorité ?","La fraude par une seule personne","La perte d'un disque dur","Les coupures réseau","L'usure du matériel",
 "Celui qui saisit une dépense ne doit pas pouvoir la valider seul."),
(1,"Qu'est-ce qu'une ACL (liste de contrôle d'accès) ?","Une liste associée à un objet précisant qui peut faire quoi dessus","Une liste de mots de passe interdits","Une liste d'utilisateurs connectés","Un journal des erreurs",
 "L'ACL est attachée à l'objet : elle énumère des sujets et leurs permissions."),
(1,"Dans une matrice d'accès, que représente une ligne ?","Un sujet et ses droits sur chaque objet","Un objet et ses sauvegardes","Une règle de pare-feu","Un journal quotidien",
 "Ligne = sujet, colonne = objet, case = droits. Lire par ligne donne les capacités, par colonne les ACL."),
(2,"Dans une matrice d'accès, lire une colonne donne :","La liste de contrôle d'accès de l'objet","Les capacités du sujet","La hiérarchie des rôles","Le niveau de classification du sujet",
 "La colonne regroupe tous les sujets autorisés sur un objet : c'est son ACL."),
(2,"Dans une matrice d'accès, lire une ligne donne :","Les capacités du sujet","La liste de contrôle d'accès de l'objet","Les attributs de l'environnement","La politique de mot de passe",
 "La ligne regroupe tout ce qu'un sujet peut faire : ce sont ses capacités."),
(2,"Quel est le principal inconvénient d'une matrice d'accès stockée telle quelle ?","Elle est très grande et surtout vide","Elle ne peut pas exprimer la lecture","Elle impose le chiffrement","Elle exige un serveur dédié par objet",
 "Peu de cases sont remplies : on stocke donc la matrice par colonnes (ACL) ou par lignes (capacités)."),
(2,"Quelle approche est dite « par capacités » ?","Le sujet détient un jeton qui prouve son droit sur l'objet","L'objet porte la liste de tous les sujets","Les droits dépendent de l'heure","Le propriétaire est toujours administrateur",
 "Une capacité est un titre transmissible ; le possesseur peut agir sans que l'objet vérifie son identité."),
(2,"Quel avantage a une ACL par rapport aux capacités ?","On voit facilement qui a accès à un objet donné","On voit facilement tout ce qu'un sujet peut faire","Elle ne nécessite aucun identifiant","Elle supprime le besoin de politique",
 "Avec les ACL, la révocation sur un objet est simple : on retire une ligne dans sa liste."),
(2,"Quelle difficulté pose la révocation avec des capacités ?","Il est difficile de retrouver et retirer tous les jetons déjà distribués","Les capacités ne peuvent jamais être copiées","Il faut redémarrer le système","Elles expirent toujours à minuit",
 "Les jetons circulent chez les sujets ; retirer un droit suppose de les repérer ou de changer l'objet."),
(2,"Qu'est-ce qu'un moniteur de référence ?","Un composant qui intercepte chaque accès et vérifie la politique","Un écran d'état du réseau","Un annuaire de mots de passe","Un outil de sauvegarde",
 "Il doit être incontournable, inviolable et assez simple pour être vérifié (Anderson, 1972)."),
(3,"Quelles propriétés définissent un moniteur de référence selon Anderson (1972) ?","Incontournable, inviolable et vérifiable","Rapide, bon marché et redondant","Anonyme, distribué et chiffré","Modulaire, extensible et documenté",
 "Si un accès pouvait le contourner, la politique ne serait plus garantie."),
(2,"Qu'est-ce que la « défense en profondeur » ?","Empiler plusieurs couches de protection indépendantes","Mettre un seul pare-feu très puissant","Cacher les serveurs","Chiffrer uniquement les sauvegardes",
 "Si une barrière cède, les suivantes limitent les dégâts : le contrôle d'accès est l'une de ces couches."),
(1,"Quelle information un journal d'accès doit-il permettre d'établir ?","Qui a accédé à quoi et quand","La couleur du badge","La version du navigateur seulement","Le coût de l'infrastructure",
 "Sans traçabilité, on ne peut ni détecter un abus ni prouver une action."),
(2,"Pourquoi interdit-on les comptes partagés entre plusieurs personnes ?","On ne peut plus attribuer une action à un individu précis","Ils consomment plus de licences","Ils ralentissent l'authentification","Ils empêchent le chiffrement",
 "L'imputabilité disparaît : le journal indique le compte, pas la personne."),
(2,"Quel est l'effet d'un « refus par défaut » (deny by default) ?","Tout ce qui n'est pas explicitement permis est refusé","Tout est permis sauf interdiction","Seuls les administrateurs accèdent","Les accès sont refusés la nuit",
 "C'est la posture sûre : un oubli dans la politique bloque au lieu d'ouvrir."),
(2,"Quel défaut a une politique « permis par défaut » ?","Un oubli de règle laisse l'accès ouvert","Elle est impossible à écrire","Elle exige trop de journaux","Elle interdit la lecture",
 "Toute situation non prévue devient autorisée, ce qui ouvre la porte aux erreurs et aux attaques."),
(1,"Quelle donnée est un facteur d'authentification « ce que l'on sait » ?","Un mot de passe","Une empreinte digitale","Une carte à puce","Un jeton matériel",
 "Les trois familles sont : ce que je sais, ce que je possède, ce que je suis."),
(1,"Quel élément est un facteur « ce que l'on possède » ?","Une carte à puce","Un code PIN mémorisé","Une empreinte digitale","Le nom de sa mère",
 "Un objet physique ou numérique détenu par l'utilisateur sert de preuve."),
(2,"Pourquoi l'authentification multifacteur renforce-t-elle un accès ?","Il faut compromettre plusieurs facteurs de familles différentes","Le mot de passe devient inutile","Elle remplace l'autorisation","Elle chiffre les fichiers",
 "Un mot de passe volé ne suffit plus : l'attaquant doit aussi détenir le second facteur."),
(2,"Un utilisateur authentifié par MFA obtient-il automatiquement tous les droits ?","Non, l'autorisation reste à vérifier séparément","Oui, le MFA vaut autorisation","Oui, mais seulement en lecture","Non, sauf pour les administrateurs",
 "Authentification et autorisation sont deux étapes distinctes."),
(1,"Quel terme désigne la preuve qu'une personne ne peut nier avoir fait une action ?","La non-répudiation","La disponibilité","L'anonymat","La rotation des clés",
 "Elle s'appuie sur des journaux fiables et des identités individuelles."),
(1,"Quelle propriété de sécurité vise à empêcher la divulgation à des personnes non autorisées ?","La confidentialité","L'intégrité","La disponibilité","La traçabilité",
 "Confidentialité, intégrité, disponibilité forment la triade CID (ou CIA en anglais)."),
(1,"Quelle propriété vise à empêcher la modification non autorisée des données ?","L'intégrité","La confidentialité","La disponibilité","La portabilité",
 "Un contrôle d'accès en écriture protège l'intégrité."),
(2,"Quel contrôle d'accès protège avant tout la disponibilité ?","Limiter qui peut arrêter ou supprimer un service","Chiffrer les messages","Classifier les documents","Imposer un mot de passe long",
 "Restreindre les droits d'arrêt, de suppression et de configuration évite les indisponibilités volontaires ou accidentelles."),
(2,"Qu'est-ce qu'un privilège élevé ?","Un droit permettant des actions étendues, comme administrer un système","Un droit de lecture seule","Une habilitation de niveau Public","Un mot de passe long",
 "Les comptes à privilèges élevés sont des cibles prioritaires, donc à contrôler et à journaliser."),
(2,"Quelle est la conséquence de l'accumulation de droits au fil des changements de poste ?","Une personne détient plus de droits que nécessaire","Les droits expirent automatiquement","Les droits deviennent inutilisables","Le journal se vide",
 "On parle de dérive des privilèges ; la revue périodique des droits la corrige."),
(2,"À quoi sert une revue périodique des droits ?","Retirer les droits devenus inutiles","Augmenter le nombre d'utilisateurs","Changer les mots de passe","Supprimer les journaux",
 "Elle confronte les droits réels à la mission actuelle de chaque personne."),
(1,"Que fait-on idéalement des droits d'un salarié qui quitte l'entreprise ?","On les retire dès son départ","On les garde trois mois","On les transfère à un collègue sans contrôle","On les laisse actifs pour archivage",
 "Un compte oublié est un accès ouvert : le processus « départ » doit désactiver les comptes."),
(2,"Quel mécanisme dit « discrétionnaire » laisse le propriétaire d'un objet décider de ses droits ?","Le DAC","Le MAC","Le Zero Trust","Le chiffrement",
 "Dans le DAC (Discretionary Access Control), c'est le propriétaire qui accorde ou retire les droits."),
(2,"Dans un modèle « obligatoire » (MAC), qui fixe la politique ?","Une autorité centrale, pas le propriétaire de l'objet","Chaque utilisateur pour ses fichiers","Le premier qui crée l'objet","Aucun contrôle central",
 "Le système impose des règles que les utilisateurs ne peuvent pas modifier."),
(2,"Quelle formulation décrit le mieux le contrôle d'accès par rôles ?","Les droits sont attachés à des rôles, les personnes reçoivent des rôles","Les droits sont attachés à chaque fichier par son créateur","Les droits dépendent seulement de l'adresse IP","Les droits dépendent de la couleur de l'étiquette",
 "Pour changer les droits d'un poste, on modifie le rôle une fois pour toutes les personnes concernées."),
(3,"Pourquoi dit-on que le contrôle d'accès est « nécessaire mais pas suffisant » ?","Il ne protège pas une donnée une fois sortie du système contrôlé","Il remplace toutes les autres mesures","Il ne s'applique qu'aux invités","Il n'agit que sur le réseau",
 "Un utilisateur autorisé peut copier une donnée ailleurs ; chiffrement, prévention de fuite et traçabilité complètent."),
(3,"Quel risque illustre le « confused deputy » (délégué abusé) ?","Un programme privilégié utilisé par un tiers pour accéder à ce que celui-ci ne pourrait pas","Un administrateur qui oublie son mot de passe","Une sauvegarde incomplète","Un certificat expiré",
 "Le programme agit avec ses propres droits à la demande d'un sujet moins privilégié ; les capacités limitent ce risque."),
(3,"Qu'est-ce que l'élévation de privilèges ?","Obtenir des droits supérieurs à ceux prévus","Réduire volontairement ses droits","Changer son mot de passe","Quitter une session",
 "Un attaquant qui exploite une faille pour devenir administrateur contourne la politique d'accès."),
(2,"Quel principe pousse à limiter la durée pendant laquelle un droit élevé reste actif ?","Le privilège temporaire (just-in-time)","Le privilège héréditaire","La délégation permanente","Le compte partagé",
 "Un droit accordé le temps d'une tâche réduit la fenêtre d'abus."),
(2,"Quelle différence y a-t-il entre identité et compte ?","L'identité représente la personne, le compte est sa représentation dans un système","Aucune différence","Le compte représente la personne, l'identité est un mot de passe","L'identité n'existe que dans les annuaires",
 "Une personne peut avoir plusieurs comptes ; la gestion des identités relie ces comptes à une seule personne."),
(2,"Pourquoi centraliser l'annuaire des identités ?","Pour créer et retirer les droits de façon cohérente","Pour supprimer l'authentification","Pour éviter les journaux","Pour avoir un seul mot de passe pour tous",
 "Un point de gestion unique facilite l'arrivée, la mutation et le départ des personnes."),
(1,"Que signifie SSO ?","Authentification unique : une connexion donne accès à plusieurs applications","Sauvegarde sécurisée en ligne","Suppression systématique des objets","Serveur de sécurité ouvert",
 "Single Sign-On : l'utilisateur s'authentifie une fois, les applications font confiance au fournisseur d'identité."),
(3,"Quel risque principal le SSO concentre-t-il ?","La compromission d'un compte ouvre plusieurs applications","Il supprime la traçabilité","Il empêche tout MFA","Il interdit les rôles",
 "Le gain de confort s'accompagne d'une cible unique : d'où l'intérêt du MFA sur le SSO."),
(2,"Quelle mesure répond à une absence de contrôle sur des droits donnés « pour dépanner » ?","Un processus d'approbation et de traçabilité des demandes de droits","Un mot de passe commun","La suppression des journaux","Le partage de compte",
 "Une demande formalisée, approuvée et datée permet de justifier chaque droit lors d'un audit."),
(3,"Pourquoi le principe de « moindre privilège » est-il difficile à tenir dans le temps ?","Les besoins changent et les droits s'accumulent sans retrait","Il interdit toute délégation","Il est incompatible avec les rôles","Il exige de supprimer les journaux",
 "Sans revue et sans processus de départ ou de mutation, les droits dérivent vers le haut."),
]
